// Modo: Run Once for Each Item.
// Hace dos cosas: normaliza lo que devuelve whisper y monta el contexto
// temporal que el modelo necesita para resolver "manana" o "el miercoles".

const j = $json;
let texto = '';

if (typeof j.text === 'string') {
  texto = j.text;                            // n8n parseo el JSON
} else if (typeof j.data === 'string') {
  try {
    texto = JSON.parse(j.data).text ?? '';   // vino como text/plain, sin parsear
  } catch (e) {
    texto = j.data;                          // output=txt, texto pelado
  }
}

// Nombres a mano: asi no dependemos de que el contenedor traiga locale es.
const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];

const ahora = DateTime.now().setZone('Europe/Madrid');
const dia = (d) => DIAS[d.weekday - 1];
const iso = (d) => d.toFormat('yyyy-LL-dd');

// La tabla de anclas existe para que el modelo NO tenga que calcular fechas:
// resolver "el jueves" pasa a ser copiar una linea. Los modelos son malos
// haciendo aritmetica de calendario y buenos copiando.
const lineas = [];
lineas.push('ahora mismo: ' + dia(ahora) + ' ' + iso(ahora) + ', las ' + ahora.toFormat('HH:mm'));
lineas.push('hoy: ' + iso(ahora));
lineas.push('mañana: ' + dia(ahora.plus({ days: 1 })) + ' ' + iso(ahora.plus({ days: 1 })));
lineas.push('pasado mañana: ' + dia(ahora.plus({ days: 2 })) + ' ' + iso(ahora.plus({ days: 2 })));

for (let i = 1; i <= 7; i++) {
  const d = ahora.plus({ days: i });
  lineas.push('el próximo ' + dia(d) + ': ' + iso(d));
}

lineas.push('dentro de una semana: ' + iso(ahora.plus({ weeks: 1 })));
lineas.push('dentro de quince días: ' + iso(ahora.plus({ days: 15 })));
lineas.push('dentro de un mes: ' + iso(ahora.plus({ months: 1 })));
lineas.push('fin de mes: ' + iso(ahora.endOf('month')));

return {
  json: {
    transcripcion: String(texto).trim(),
    ahora: ahora.toFormat("yyyy-LL-dd'T'HH:mm:ss"),
    anclas: lineas.join('\n'),
  },
};

