// Modo: Run Once for Each Item.
// Junta transcripcion cruda y salida del modelo, valida la fecha y arma el .md.

const ctx = $('Preparar contexto').first().json;
const cruda = String(ctx.transcripcion ?? '').trim();
const meta = $('Mensaje entrante').first().json;

const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

// El modelo deberia devolver JSON pelado, pero a veces lo envuelve en vallas.
function parsearJson(s) {
  const t = String(s ?? '').trim()
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/, '')
    .trim();
  try { return JSON.parse(t); } catch (e) { /* probamos a recortar */ }
  const i = t.indexOf('{');
  const f = t.lastIndexOf('}');
  if (i !== -1 && f > i) {
    try { return JSON.parse(t.slice(i, f + 1)); } catch (e) { /* nos rendimos */ }
  }
  return null;
}

const modelo = parsearJson($json.text ?? $json.response ?? '') ?? {};
const modeloOk = Object.keys(modelo).length > 0;

// Si no ha contestado ningun modelo, averiguamos por que y cuando vuelve.
// El nodo deja pasar el error como dato en vez de tumbar la ejecucion, que
// perderia la nota: el offset ya ha avanzado y Telegram no la reenvia.
let avisoModelo = '';
if (!modeloOk) {
  const crudo = JSON.stringify($json ?? {});
  const sinCuota = /429|quota|RESOURCE_EXHAUSTED|rate.?limit/i.test(crudo);

  if (!sinCuota) {
    avisoModelo = 'El modelo no respondio: guardada la transcripcion cruda.';
  } else if (/PerDay|free_tier_requests|per day/i.test(crudo)) {
    // Las cuotas diarias del tier gratuito de Google se reinician a
    // medianoche hora del Pacifico.
    const reset = DateTime.now()
      .setZone('America/Los_Angeles')
      .plus({ days: 1 })
      .startOf('day')
      .setZone('Europe/Madrid');
    avisoModelo = 'Sin cuota diaria de modelo. Guardada la transcripcion cruda, ' +
      'sin limpiar ni clasificar. La cuota vuelve sobre las ' +
      reset.toFormat('HH:mm') + ' del ' + reset.toFormat('dd/LL') + '.';
  } else {
    const m = crudo.match(/retryDelay[^0-9]*([0-9]+)s/i) || crudo.match(/retry in ([0-9.]+)s/i);
    const seg = m ? Math.ceil(Number(m[1])) : null;
    avisoModelo = 'Modelo a tope de peticiones por minuto. Guardada la ' +
      'transcripcion cruda' + (seg ? ', reintentalo en ' + seg + ' s.' : '.');
  }
}

// Si el modelo falla, la nota se guarda igual con la transcripcion cruda.
// Perder la nota seria peor que guardarla fea.
const limpio = String(modelo.limpio ?? cruda).trim();
let titulo = String(modelo.titulo ?? cruda.split(/\s+/).slice(0, 8).join(' ')).trim();
titulo = titulo.replace(/\s+/g, ' ').slice(0, 80) || 'Nota sin título';

const TIPOS = ['nota', 'tarea', 'evento'];
let tipo = String(modelo.tipo ?? 'nota').toLowerCase().trim();
if (!TIPOS.includes(tipo)) tipo = 'nota';

// --- la fecha, que es lo que mas se tuerce ---
const ahora = DateTime.fromISO(ctx.ahora, { zone: 'Europe/Madrid' });
let cuando = null;
let avisoFecha = '';

const cuandoBruto = modelo.cuando;
if (typeof cuandoBruto === 'string' && cuandoBruto.trim()) {
  const d = DateTime.fromISO(cuandoBruto.trim(), { zone: 'Europe/Madrid' });
  if (!d.isValid) {
    avisoFecha = 'No he entendido la fecha, la dejo vacía.';
  } else if (Math.abs(d.diff(ahora, 'years').years) > 5) {
    // Sintoma tipico de que el modelo se ha inventado el año.
    avisoFecha = 'La fecha que salía (' + d.toFormat('yyyy-LL-dd') + ') no tiene sentido, la dejo vacía.';
  } else {
    cuando = d;
    if (d < ahora) avisoFecha = 'Ojo: esa fecha ya ha pasado.';
  }
}

// Un evento sin fecha no es un evento. Asi el workflow de avisos de la fase 4
// puede fiarse de que "cuando" relleno equivale a tipo evento.
if (tipo === 'evento' && !cuando) tipo = 'tarea';

const tags = (Array.isArray(modelo.tags) ? modelo.tags : [])
  .map(t => String(t).toLowerCase().trim().replace(/["'\[\],]/g, '').replace(/\s+/g, '-'))
  .filter(Boolean)
  .slice(0, 3);

const slug = titulo
  .normalize('NFD').replace(/[^\x00-\x7F]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 50) || 'nota';

const creado = DateTime.fromISO(meta.fecha).setZone('Europe/Madrid');
const nombreFichero = creado.toFormat('yyyy-LL-dd-HHmm') + '-' + slug + '.md';

const comillas = (s) => '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const crudaCitada = (cruda || '(transcripción vacía)')
  .split('\n').map(l => '> ' + l).join('\n');

const contenido = [
  '---',
  'tipo: ' + tipo,
  'titulo: ' + comillas(titulo),
  'creado: ' + creado.toFormat("yyyy-LL-dd'T'HH:mm:ss"),
  'cuando: ' + (cuando ? cuando.toFormat("yyyy-LL-dd'T'HH:mm:ss") : ''),
  'avisado: false',
  'tags: [' + tags.join(', ') + ']',
  // Marca para repescar cuando vuelva la cuota: grep -rl 'revisar: true' vault/
  modeloOk ? null : 'revisar: true',
  '---',
  '',
  '# ' + titulo,
  '',
  limpio,
  '',
  '<!-- transcripción cruda -->',
  crudaCitada,
  '',
].filter(l => l !== null).join('\n');

// Como se lo contamos por Telegram.
const fechaHumana = cuando
  ? DIAS[cuando.weekday - 1] + ' ' + cuando.day + ' de ' + MESES[cuando.month - 1] +
    ', ' + cuando.toFormat('HH:mm')
  : null;

const partes = [];
if (tipo === 'evento') {
  partes.push('Evento: ' + titulo);
  partes.push(fechaHumana);
} else {
  partes.push('Apuntado (' + tipo + '): ' + titulo);
}
if (avisoFecha) partes.push(avisoFecha);
if (avisoModelo) partes.push(avisoModelo);

return {
  json: {
    tipo,
    titulo,
    tags,
    cuando: cuando ? cuando.toFormat("yyyy-LL-dd'T'HH:mm:ss") : null,
    nombreFichero,
    contenido,
    resumen: partes.filter(Boolean).join('\n'),
    esEvento: tipo === 'evento',
    chat_id: meta.chat_id,
    message_id: meta.message_id,
    modeloOk,
  },
};

// Modo: Run Once for Each Item.
// Aparca el evento a la espera de que pulses un boton. Solo hay un usuario,
// asi que con guardar UNA pendiente a la vez sobra: si dictas dos eventos
// seguidos, el segundo tapa al primero y el boton viejo queda caducado.

const estado = $getWorkflowStaticData('global');
const nota = $json;

// El message_id de tu nota de voz identifica la pendiente y cabe de sobra en
// los 64 bytes que Telegram deja meter en callback_data.
const token = String(nota.message_id);

estado.pendiente = {
  token,
  nombreFichero: nota.nombreFichero,
  contenido: nota.contenido,
  resumen: nota.resumen,
  creado: Date.now(),
};

return { json: { ...nota, token } };

// Modo: Run Once for Each Item.
// Llega una pulsacion de boton. Decide si hay que guardar, tirar, o si la
// pregunta ya no vale.

const CADUCIDAD_MS = 30 * 60 * 1000;

const estado = $getWorkflowStaticData('global');
const cb = $json;

const [accion, token] = String(cb.datos ?? '').split(':');
const p = estado.pendiente;
const vigente = p && p.token === token && (Date.now() - p.creado) < CADUCIDAD_MS;

let resultado = 'caducado';
let nombreFichero = '';
let contenido = '';

if (vigente) {
  resultado = accion === 'ok' ? 'guardar' : 'tirar';
  // El contenido solo viaja por la rama que lo va a escribir. Asi el camino
  // de descarte no lleva encima nada que pueda acabar en el vault.
  if (resultado === 'guardar') {
    nombreFichero = p.nombreFichero;
    contenido = p.contenido;
  }
  estado.pendiente = null;
} else if (p && (Date.now() - p.creado) >= CADUCIDAD_MS) {
  estado.pendiente = null;   // limpiamos la basura de paso
}

const textos = {
  guardar: '✅ Guardado.\n' + (vigente ? p.resumen : ''),
  tirar: '🗑 Tirado. No se ha guardado nada.',
  caducado: '⌛ Esa pregunta ya no vale: o la respondiste, o la tapó una nota más nueva.',
};

return {
  json: {
    resultado,
    guardar: resultado === 'guardar',
    nombreFichero,
    contenido,
    chat_id: cb.chat_id,
    message_id: cb.message_id,
    callback_id: cb.callback_id,
    texto: textos[resultado],
  },
};
